// Function to add a new post to the feed
void addPost(Node *&head, int postId) {
    Node *newNode = new Node();
    newNode->postId = postId;
    newNode->next = head;
    head = newNode;
}

// Function to display all posts in the feed
void displayFeed(Node *head) {
    while (head != nullptr) {
        std::cout << head->postId << std::endl;
        head = head->next;
    }
}

// Function to remove a post from the feed
void removePost(Node *&head, int postId) {
    if (head == nullptr) {
        return;
    }
    if (head->postId == postId) {
        Node *temp = head;
        head = head->next;
        delete temp;
        return;
    }
    Node *current = head;
    while (current->next != nullptr) {
        if (current->next->postId == postId) {
            Node *temp = current->next;
            current->next = current->next->next;
            delete temp;
            return;
        }
        current = current->next;
    }
}

