// Example of a binary search tree node
struct Node {
    int data;
    Node *left;
    Node *right;
};

// Example of inserting a node into the binary search tree
Node *insertNode(Node *root, int data) {
    if (root == nullptr) {
        root = new Node();
        root->data = data;
        root->left = nullptr;
        root->right = nullptr;
    } else if (data < root->data) {
        root->left = insertNode(root->left, data);
    } else if (data > root->data) {
        root->right = insertNode(root->right, data);
    }
    return root;
}

// Example of deleting a node from the binary search tree
Node *deleteNode(Node *root, int data) {
    if (root == nullptr) {
        return root;
    }
    if (data < root->data) {
        root->left = deleteNode(root->left, data);
    } else if (data > root->data) {
        root->right = deleteNode(root->right, data);
    } else {
        if (root->left == nullptr) {
            Node *temp = root->right;
            delete root;
            return temp;
        } else if (root->right == nullptr) {
            Node *temp = root->left;
            delete root;
            return temp;
        }
        Node *temp = root->right;
        while (temp->left != nullptr) {
            temp = temp->left;
        }
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data);
    }
    return root;
}

// Example of printing the binary search tree using in-order traversal
void printInOrder(Node *root) {
    if (root != nullptr) {
        printInOrder(root->left);
        std::cout << root->data << " ";
        printInOrder(root->right);
    }
}

int main() {
    Node *root = nullptr;
    root = insertNode(root, 50);
    root = insertNode(root, 30);
    root = insertNode(root, 20);
    root = insertNode(root, 40);
    root = insertNode(root, 70);
    root = insertNode(root, 60);
    root = insertNode(root, 80);
    std::cout << "Before deletion: ";
    printInOrder(root);
    root = deleteNode(root, 20);
    std::cout << "\nAfter deletion: ";
    printInOrder(root);
    // Introduce the bug: iterator invalidation during container modification
    for (Node *current = root; current != nullptr; current = current->right) {
        if (current->data == 40) {
            root = deleteNode(root, 40);
        }
    }
    std::cout << "\nAfter bug introduction: ";
    printInOrder(root);
    return 0;
}

