// Define a simple binary search tree node class
class Node {
  public:
    int studentId;
    double grade;
    Node *left;
    Node *right;

    Node(int id, double g) {
        studentId = id;
        grade = g;
        left = nullptr;
        right = nullptr;
    }
};

// Function to insert a node into the binary search tree
void insertNode(Node *&root, int studentId, double grade) {
    if (root == nullptr) {
        root = new Node(studentId, grade);
    } else if (studentId < root->studentId) {
        insertNode(root->left, studentId, grade);
    } else {
        insertNode(root->right, studentId, grade);
    }
}

// Function to print the student grades (vulnerable to type mismatch)
void printGrades(Node *root) {
    if (root != nullptr) {
        printGrades(root->left);
        std::printf("Student ID: %d, Grade: %d\n", root->studentId,
                    root->grade);
        printGrades(root->right);
    }
}

int main() {
    Node *root = nullptr;
    insertNode(root, 1, 85.5);
    insertNode(root, 2, 90.0);
    insertNode(root, 3, 78.2);
    printGrades(root);
    return 0;
}

