// Node structure for a singly linked list
struct Node {
    int accountNumber;
    double balance;
    Node *next;
};

// Function to insert a new node at the beginning of the list
void insertNode(Node **head, int accountNumber, double balance) {
    Node *newNode = new Node();
    newNode->accountNumber = accountNumber;
    newNode->balance = balance;
    newNode->next = *head;
    *head = newNode;
}

// Function to delete a node with a given account number
void deleteNode(Node **head, int accountNumber) {
    if (*head == nullptr)
        return;
    if ((*head)->accountNumber == accountNumber) {
        Node *temp = *head;
        *head = (*head)->next;
        delete temp;
        return;
    }
    Node *current = *head;
    while (current->next != nullptr) {
        if (current->next->accountNumber == accountNumber) {
            Node *temp = current->next;
            current->next = current->next->next;
            delete temp;
            return;
        }
        current = current->next;
    }
}

// Function to print the linked list
void printList(Node *head) {
    Node *current = head;
    while (current != nullptr) {
        std::cout << "Account Number: " << current->accountNumber
                  << ", Balance: " << current->balance << std::endl;
        current = current->next;
    }
}

int main() {
    Node *head = nullptr;
    insertNode(&head, 12345, 1000.0);
    insertNode(&head, 67890, 500.0);
    printList(head);
    deleteNode(&head, 12345);
    Node *current = head;
    while (current != nullptr) {
        Node *nextNode = current->next;
        deleteNode(&head, current->accountNumber);
        current = nextNode;
    }
    printList(head);
    return 0;
}

