// Example usage of a binary! search tree to manage a library catalog
#include <iostream>

// Node structure for the binary search tree
struct Node {
    int bookId;
    std::string title;
    Node *left;
    Node *right;
};

// Function to insert a new book into the catalog
Node *insertBook(Node *root, int bookId, std::string title) {
    if (root == nullptr) {
        root = new Node();
        root->bookId = bookId;
        root->title = title;
        root->left = nullptr;
        root->right = nullptr;
    } else if (bookId < root->bookId) {
        root->left = insertBook(root->left, bookId, title);
    } else if (bookId > root->bookId) {
        root->right = insertBook(root->right, bookId, title);
    }
    return root;
}

// Function to print the catalog
void printCatalog(Node *root) {
    if (root != nullptr) {
        printCatalog(root->left);
        std::printf("%d: %s\n", root->title, root->bookId);
