// HashTable class representing an e-commerce shopping cart
class HashTable {
  public:
    HashTable(int size) {
        this->size = size;
        this->table = new int *[size];
        for (int i = 0; i < size; i++) {
            this->table[i] = nullptr;
        }
    }
    ~HashTable() {
        for (int i = 0; i < size; i++) {
            if (this->table[i] != nullptr) {
                delete[] this->table[i];
            }
        }
        delete[] this->table;
    }
    void insert(int key, int value) {
        int index = key % size;
        if (table[index] == nullptr) {
            table[index] = new int[2];
            table[index][0] = key;
            table[index][1] = value;
        } else {
            int *temp = table[index];
            while (temp[0] != key) {
                temp += 2;
            }
            temp[1] = value;
        }
    }
    int get(int key) {
        int index = key % size;
        if (table[index] != nullptr) {
            int *temp = table[index];
            while (temp[0] != key) {
                temp += 2;
            }
            return temp[1];
        }
        return -1; // Return -1 if key not found
    }

  private:
    int size;
    int **table;
};

int main() {
    HashTable cart(10);
    int productID;
    int quantity;
    // Read productID and quantity from input
    std::cin >> productID >> quantity;
    cart.insert(productID, quantity);
    // Print the quantity of the product
    std::cout << cart.get(productID) << std::endl;
    return 0;
}

