class GameInventory {
  private:
    InventoryItem *head;

  public:
    GameInventory() {
        head = nullptr;
    }

    void addItem(char *name, int qty) {
        InventoryItem *newItem = new InventoryItem(name, qty);
        if (head == nullptr) {
            head = newItem;
