            InventoryItem *current = head;
            while (current->nextItem != nullptr) {
                current = current->nextItem;
            }
            current->nextItem = newItem;
        }
    }

    void printInventory() {
        InventoryItem *current = head;
        while (current != nullptr) {
            std::cout << current->itemName << " x" << current->quantity
                      << std::endl;
            current = current->nextItem;
        }
    }
};

