class CompressionUtility {
  public:
    void compressFile(std::string inputFile, std::string outputFile) {
        int fileSize;
        std::ifstream inputFileStream(inputFile);
        inputFileStream.seekg(0, std::ios::end);
        fileSize = inputFileStream.tellg();
        int compressedFileSize = fileSize;
        inputFileStream.seekg(0, std::ios::beg);
        char *fileBuffer = new char[fileSize];
        inputFileStream.read(fileBuffer, fileSize);
        for (int i = 0; i < compressedFileSize; i++) {
            if (i > 0 && fileBuffer[i] == fileBuffer[i - 1]) {
                compressedFileSize--;
            }
        }
        std::ofstream outputFileStream(outputFile);
        outputFileStream.write(fileBuffer, compressedFileSize);
        delete[] fileBuffer;
    }
};
int main() {
    CompressionUtility utility;
    utility.compressFile("input.txt", "output.txt");
    return 0;
}

